#!/usr/bin/env bun
// Vendor @chenglou/pretext for /garage/pretext: src/client/garage/pretext.lib.js
// and the declaration beside it, pretext.lib.d.ts.
//
// WHY A SCRIPT. 0.0.7 was vendored on 2026-06-02 (978f1f7a) with no recorded
// recipe, and no bun build flag set reproduces its bytes, so the 1.0.0 update
// had to start from a guess. This is the recipe: one pinned tarball, checked
// against the registry's sha512, bundled by the bun running this script. Run it
// under the pinned bun (config/bun-pin.json) so the minifier is the one CI uses.
//
// The bundle is pretext's main entry only (`dist/layout.js`), ES module,
// minified. The page imports nothing from `@chenglou/pretext/rich-inline`.
// build.ts minifies it again as a page-scoped /a/ asset and ships these bytes
// as the readable twin, /garage/pretext.lib.src.js.
//
// The declaration is upstream's dist/layout.d.ts with its one import from
// ./analysis.js replaced by the three string unions it names, so the file
// stands alone. If upstream reshapes that import, the replace finds nothing
// and this script stops rather than writing a declaration that can't resolve.
//
// Updating: set VERSION and INTEGRITY from
// `curl -s https://registry.npmjs.org/@chenglou/pretext | jq '.versions["X"].dist'`,
// run `bun tools/vendor-pretext.ts`, then read that version's CHANGELOG.md
// for the page's calls and prose. docs/DEPENDENCIES.md has the rest.

import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

const VERSION = "1.0.0";
const INTEGRITY = "sha512-BxKiDMxWJhyzL8asvcgg3T9YnUU7OUFsKO8oRaR2SYAPX4Sh2wM9gqTBjrBaZ4fnl84cEQ8czC0Q1M83z3chsA==";
const TARBALL = `https://registry.npmjs.org/@chenglou/pretext/-/pretext-${VERSION}.tgz`;
const OUT_JS = "src/client/garage/pretext.lib.js";
const OUT_DTS = "src/client/garage/pretext.lib.d.ts";
const BANNER = `/*! @chenglou/pretext ${VERSION} | MIT License, Copyright (c) 2026 Pretext contributors | github.com/chenglou/pretext */`;

const run = async (cmd: string[]): Promise<void> => {
  const proc = Bun.spawn(cmd, { stdout: "inherit", stderr: "inherit" });
  if ((await proc.exited) !== 0) throw new Error(`${cmd.join(" ")} exited ${proc.exitCode}`);
};

const work = await mkdtemp(join(tmpdir(), "vendor-pretext-"));
try {
  const res = await fetch(TARBALL);
  if (!res.ok) throw new Error(`${TARBALL}: HTTP ${res.status}`);
  const tgz = new Uint8Array(await res.arrayBuffer());
  const got = `sha512-${new Bun.CryptoHasher("sha512").update(tgz).digest("base64")}`;
  if (got !== INTEGRITY) throw new Error(`${TARBALL}: integrity ${got}, expected ${INTEGRITY}`);
  await writeFile(join(work, "pretext.tgz"), tgz);
  await run(["tar", "-xzf", join(work, "pretext.tgz"), "-C", work]);
  const dist = join(work, "package", "dist");

  await run([process.execPath, "build", join(dist, "layout.js"), "--format=esm", "--minify", `--banner=${BANNER}`, `--outfile=${OUT_JS}`]);

  const analysis = await readFile(join(dist, "analysis.d.ts"), "utf8");
  const union = (name: string): string => {
    const m = analysis.match(new RegExp(`^export type ${name} = [^;]+;$`, "m"));
    if (!m) throw new Error(`analysis.d.ts no longer declares ${name} as a one-line type`);
    return m[0].replace(/^export /, "");
  };
  const IMPORT = "import { type SegmentBreakKind, type WhiteSpaceMode, type WordBreakMode as AnalysisWordBreakMode } from './analysis.js';\n";
  const layout = await readFile(join(dist, "layout.d.ts"), "utf8");
  if (!layout.startsWith(IMPORT)) throw new Error("layout.d.ts no longer opens with the analysis.js import this script inlines");
  const inlined = [union("SegmentBreakKind"), union("WhiteSpaceMode"), union("WordBreakMode").replace("type WordBreakMode", "type AnalysisWordBreakMode")].join(
    "\n",
  );
  const dts =
    `// @chenglou/pretext ${VERSION}, dist/layout.d.ts with ./analysis.js inlined. Generated by tools/vendor-pretext.ts.\n` +
    inlined +
    "\n" +
    layout.slice(IMPORT.length).replace(/\n\/\/# sourceMappingURL=.*$/, "\n");
  await writeFile(OUT_DTS, dts);
  console.log(`vendored @chenglou/pretext ${VERSION} with bun ${Bun.version}: ${OUT_JS} (${(await readFile(OUT_JS)).length} B), ${OUT_DTS}`);
} finally {
  await rm(work, { recursive: true, force: true });
}
